    about_story_h: "Mon histoire",
    about_story_p1: "J'avais 15 ans en 1985, je vivais en Tchécoslovaquie sous le régime communiste. Les frontières étaient gardées par des barbelés, l'économie était en ruines et les gens n'avaient pas le droit de voyager ni de penser librement. Ceux qui voulaient agir risquaient leur vie en traversant la frontière ou finissaient en prison. Ma famille était divisée : certains proches avaient fui à l'étranger, d'autres étaient restés.",
    about_story_p2: "Je ne sais toujours pas exactement comment, mais mes proches ont réussi à faire passer clandestinement un Commodore 64 à travers la frontière. J'étais enthousiaste. J'ai commencé à programmer — en sauvegardant sur cassette — et le premier jeu que j'ai écrit était Mastermind.",
    about_story_p3: "Quarante ans plus tard, j'y suis revenu. J'ai décidé de recréer ce jeu, cette fois pour iOS et Android. Je suis directeur de Colegio Solutions s.r.o., où nous développons des logiciels avec mes associés. Mastermind est notre première application mobile — et j'espère pas la dernière.",
