    about_story_h: "我的故事",
    about_story_p1: "1985年，我15岁，生活在共产主义政权统治下的捷克斯洛伐克。边境被铁丝网封锁，经济一片凋敝，人们无法自由旅行，也无法自由思考。敢于行动的人要么冒着生命危险越境，要么身陷囹圄。我的家庭也因此分裂：一部分亲戚逃往了国外，另一些则留了下来。",
    about_story_p2: "我至今不知道他们是怎么做到的，但亲戚们设法将一台Commodore 64偷偷运过了边境。我欣喜若狂，开始学习编程，存储介质是磁带，我编写的第一款游戏就是Mastermind。",
    about_story_p3: "四十年后，我重拾旧梦。这一次，我决定为iOS和Android重新打造这款游戏。我是Colegio Solutions s.r.o.的负责人，与合伙人共同从事软件开发和IT项目。Mastermind是我们的第一款移动应用，希望不是最后一款。",
