    about_who_h: "हम कौन हैं",
    about_who_p1: "Colegio Solutions s.r.o. एक चेक कंपनी है जो प्राग के पूर्व में Sibřina गांव में स्थित है।",
    about_who_p2: "Mastermind हमारा पहला मोबाइल गेम है — iOS के लिए SwiftUI और Android के लिए Kotlin & Jetpack Compose में नेटिव रूप से बनाया गया।",
