    about_v4_h: "गुणवत्ता", about_v4_p: "नेटिव SwiftUI और Kotlin/Compose, कोई तृतीय-पक्ष SDK नहीं, कोई विज्ञापन नहीं।",
    about_info_h: "कंपनी जानकारी",
    about_story_h: "मेरी कहानी",
    about_story_p1: "1985 में मेरी उम्र 15 साल थी और मैं साम्यवादी शासन के अधीन चेकोस्लोवाकिया में रहता था। सीमाएँ काँटेदार तारों से बंद थीं, अर्थव्यवस्था तबाह थी और लोग स्वतंत्र रूप से यात्रा या सोचने की आजादी नहीं रखते थे। जो लोग कुछ करने की हिम्मत रखते थे वे या तो सीमा पार करते हुए जान जोखिम में डालते, या जेल जाते थे। मेरा परिवार भी बंटा हुआ था, कुछ रिश्तेदार विदेश भाग गए, बाकी रह गए।",
    about_story_p2: "मुझे अभी तक ठीक से नहीं पता कि वह कैसे हुआ, लेकिन मेरे रिश्तेदारों ने Commodore 64 को छुपाकर सीमा पार करा दिया। मैं बहुत उत्साहित हो गया। मैंने प्रोग्रामिंग शुरू की, कैसेट टेप पर सेव करते हुए, और मैंने जो पहला गेम लिखा वह Mastermind था।",
    about_story_p3: "चालीस साल बाद मैं उस गेम पर वापस आया। मैंने इसे दोबारा बनाने का फैसला किया, इस बार iOS और Android के लिए। मैं Colegio Solutions s.r.o. का निदेशक हूँ जहाँ हम अपने साथियों के साथ सॉफ्टवेयर विकास और IT परियोजनाओं पर काम करते हैं। Mastermind हमारा पहला मोबाइल एप है, और उम्मीद है कि आखिरी नहीं।",
    contact_h2: "संपर्क करें",
    contact_p: "कोई सवाल, बग मिला, या सुझाव देना चाहते हैं? हम आपसे सुनना पसंद करेंगे।",
    knuth_fact: "🧠 क्या आप जानते हैं? डोनाल्ड क्नूथ ने 1976 में सिद्ध किया कि मिनीमैक्स एल्गोरिदम का उपयोग करके किसी भी कोड को 5 या उससे कम प्रयासों में हल किया जा सकता है — यह क्लासिक संस्करण (6 रंग, 4 स्थान) का सैद्धांतिक इष्टतम है। 3 प्रयासों में हल करना असाधारण है।",
