    about_story_h: "Minha história",
    about_story_p1: "Eu tinha 15 anos em 1985 e vivia na Tchecoslováquia sob o regime comunista. As fronteiras estavam seladas com arame farpado, a economia estava em ruínas e as pessoas não podiam viajar nem pensar livremente. Quem ousava agir arriscava a vida tentando cruzar a fronteira ou acabava na prisão. Minha família estava dividida: alguns parentes haviam fugido para o exterior, outros ficaram.",
    about_story_p2: "Até hoje não sei exatamente como, mas meus parentes conseguiram contrabandear um Commodore 64 pela fronteira. Fiquei animadíssimo. Comecei a programar, salvando em fita cassete, e o primeiro jogo que escrevi foi Mastermind.",
    about_story_p3: "Quarenta anos depois, voltei a isso. Decidi recriar o jogo, desta vez para iOS e Android. Sou diretor da Colegio Solutions s.r.o., onde, junto com meus sócios, desenvolvemos software e projetos de TI. Mastermind é nosso primeiro aplicativo móvel, e espero que não seja o último.",
