    about_story_p1: "Saya berusia 15 tahun pada tahun 1985 dan tinggal di Cekoslowakia di bawah pemerintahan komunis. Perbatasan dijaga dengan kawat berduri, ekonomi hancur, dan orang-orang tidak bebas bepergian atau berpikir. Mereka yang berani bertindak mempertaruhkan nyawa saat menyeberangi perbatasan atau berakhir di penjara. Keluargaku terbagi: sebagian kerabat melarikan diri ke luar negeri, sebagian lainnya tetap tinggal.",
