    about_story_h: "Min historia",
    about_story_p1: "Jag var 15 år gammal 1985 och bodde i Tjeckoslovakien under kommunistiskt styre. Gränserna var stängda med taggtråd, ekonomin låg i ruiner och folk fick varken resa eller tänka fritt. De som vågade handla riskerade livet vid gränsövergångar eller hamnade i fängelse. Min familj var splittrad: en del släktingar hade flytt utomlands, resten stannade kvar.",
    about_story_p2: "Jag vet fortfarande inte exakt hur, men mina släktingar lyckades smuggla in en Commodore 64 över gränsen. Jag var hänförd. Jag började programmera med kassettband som lagringsmedium, och det första spelet jag skrev var Mastermind.",
    about_story_p3: "Fyrtio år senare återvände jag till det. Jag bestämde mig för att göra om spelet, den här gången för iOS och Android. Jag är VD för Colegio Solutions s.r.o., där jag tillsammans med mina partners arbetar med mjukvaruutveckling och IT-projekt. Mastermind är vår första mobilapp, och förhoppningsvis inte den sista.",
