    about_story_h: "Câu chuyện của tôi",
    about_story_p1: "Năm 1985, tôi 15 tuổi và sống ở Tiệp Khắc dưới chế độ cộng sản. Biên giới bị phong tỏa bằng dây thép gai, nền kinh tế sụp đổ, và người dân không được tự do đi lại hay suy nghĩ. Những ai dám hành động hoặc liều mạng vượt biên hoặc bị tống vào tù. Gia đình tôi cũng bị chia cắt: một số người thân đã chạy ra nước ngoài, số còn lại ở lại.",
    about_story_p2: "Tôi vẫn không biết chính xác bằng cách nào, nhưng người thân của tôi đã lén đưa một chiếc Commodore 64 qua biên giới. Tôi rất phấn khích. Tôi bắt đầu lập trình lưu trữ bằng băng cassette, và trò chơi đầu tiên tôi viết là Mastermind.",
    about_story_p3: "Bốn mươi năm sau, tôi quay lại với nó. Tôi quyết định làm lại trò chơi này, lần này cho iOS và Android. Tôi là giám đốc của Colegio Solutions s.r.o., nơi tôi cùng các cộng sự phát triển phần mềm và các dự án CNTT. Mastermind là ứng dụng di động đầu tiên của chúng tôi, và hy vọng không phải là cuối cùng.",
