    about_info_h: "Інформація про компанію",
    about_story_h: "Моя історія",
    about_story_p1: "Мені було 15 років у 1985 році, і я жив у Чехословаччині під владою комуністів. Кордони були огороджені колючим дротом, економіка лежала в руїнах, а люди не мали права вільно подорожувати чи думати. Ті, хто наважувався діяти, або ризикували життям при перетині кордону або потрапляли за грати. Моя родина була розділена: частина рідних втекла за кордон, інші залишились.",
    about_story_p2: "Я досі не знаю, як це сталося, але родичі зуміли таємно переправити через кордон комп'ютер Commodore 64. Я був у захваті. Почав програмувати, зберігаючи на касетах, і першою грою, яку я написав, був Mastermind.",
    about_story_p3: "Сорок років потому я повернувся до нього. Вирішив відтворити гру, цього разу для iOS та Android. Я є директором Colegio Solutions s.r.o., де разом з партнерами займаюсь розробкою ПЗ та IT-проєктами. Mastermind — наш перший мобільний застосунок, і сподіваюсь, не останній.",
