    about_v1_h: "Sadekarî", about_v1_p: "bê tevlihevî, bê plansaziyên tarî, bê abone.",
    about_v2_h: "Gihîştbarî", about_v2_p: "sêwiraneke ewle ji bo kor-ê rengê, 50 ziman.",
