    about_v4_h: "Kalîte", about_v4_p: "SwiftUI û Kotlin/Compose yên xwezayî, bê SDK yên sêyemîn, bê reklam.",
    about_info_h: "Agahdariya pargîdanî",
    about_story_h: "Çîroka min",
    about_story_p1: "Di sala 1985an de min 15 sal hebûn û ez li Çekoslovakyayê di bin desthilatdariya komunîstan de dijîyam. Sinor bi têlên dirav girtî bûn, aborî hilweşiyabû û mirovan azadiya gerandin û fikirîna xwe tune bû. Yên ku cesaret dikirin tevdigerin yan jiyana xwe di dema derbazkirina sinor de dişixulandin yan jî dihatin avêtin zindanê. Malbata min dabeşbûyî bû: beşek ji xizmên min reviyabûn derve, beşêke din jî mabûn.",
    about_story_p2: "Heta îrojê jî nizanim çawa bû, lê xizmên min karîbûn komputerekî Commodore 64 bi dizî ji sinor derbas bikin. Ez pir kêfxweş bûm. Min dest bi bernamezaniyê kir bi kasetê tomar dikir, û yekem lîstika ku min nivîsand Mastermind bû.",
    about_story_p3: "Çil sal şûnda, min vegeriya ser wê. Min biryar da ku vê lîstikê ji nû ve ava bikim, vê carê ji bo iOS û Android. Ez rêvebera Colegio Solutions s.r.o. me, ku ez û hevkarên xwe li ser pêşveçûna nermalava û projeyên IT dixebitin. Mastermind yekem sepana mobîl a me ye, û hêvî dikim ya dawî nebe.",
