    about_story_p2: "Bu gün də dəqiq bilmirəm necə baş verdi, amma qohumlarım bir Commodore 64 kompüterini gizlicə sərhəddən keçirtməyi bacardılar. Çox sevincdim. Proqramlaşdırmağa başladım kassetə yazaraq, və yazdığım ilk oyun Mastermind oldu.",
