    about_who_h: "Hvem vi er",
    about_who_p1: "Colegio Solutions s.r.o. er et tjekkisk softwarefirma grundlagt i Sibřina, en lille landsby øst for Prag. Vi laver fokuserede, gennemarbejdede applikationer — værktøjer og spil, der er enkle at bruge og sjove at interagere med.",
    about_who_p2: "Mastermind er vores første mobilspil — bygget nativt til iOS med SwiftUI og til Android med Kotlin & Jetpack Compose — med dyb respekt for det originale brætspil, der har udfordret hjerner siden 1970.",
    about_val_h: "Vores værdier",
