    about_v4_h: "Kvalitet",
    about_v4_p: "nativ SwiftUI og Kotlin/Compose, ingen tredjeparts-SDK'er, ingen reklamer.",
    about_info_h: "Virksomhedsinfo",
    about_story_h: "Min historie",
    about_story_p1: "I 1985 var jeg 15 år og boede i Tjekkoslovakiet under det kommunistiske styre. Grænserne var lukket med pigtråd, økonomien lå i ruiner, og folk kunne ikke frit rejse eller tænke selv. De, der turde handle, risikerede enten livet ved at krydse grænsen eller endte i fængsel. Min egen familie var splittet: nogle slægtninge var flygtet til udlandet, andre blev tilbage.",
    about_story_p2: "Jeg ved stadig ikke præcis hvordan, men mine slægtninge fik smuglet en Commodore 64 over grænsen. Jeg var begejstret. Jeg begyndte at programmere — og gemte på et kassettebånd — og det første spil, jeg skrev, var Mastermind.",
    about_story_p3: "Fyrre år senere vendte jeg tilbage til det. Jeg besluttede at bygge spillet igen, denne gang til iOS og Android. Jeg er direktør for Colegio Solutions s.r.o., hvor jeg sammen med mine partnere udvikler software og arbejder på it-projekter. Mastermind er vores første mobilapp — og forhåbentlig ikke den sidste.",
