    about_info_h: "Dades de l'empresa",
    about_story_h: "La meva història",
    about_story_p1: "El 1985 tenia 15 anys i vivia a Txecoslovàquia sota el règim comunista. Les fronteres estaven tancades amb filferro espinós, l'economia estava en ruïnes i la gent no era lliure de viatjar ni de pensar per si mateixa. Els qui s'atrevien a actuar arriscaven la vida creuant la frontera o acabaven a la presó. La meva pròpia família estava dividida: alguns parents havien fugit a l'estranger, d'altres s'hi havien quedat.",
    about_story_p2: "Encara no sé exactament com, però els meus parents van aconseguir passar de contraban un Commodore 64 per la frontera. Estava entusiasmat. Vaig començar a programar — desant en una cinta de casset — i el primer joc que vaig escriure va ser Mastermind.",
    about_story_p3: "Quaranta anys més tard, hi vaig tornar. Vaig decidir crear el joc de nou, aquesta vegada per a iOS i Android. Soc el director de Colegio Solutions s.r.o., on juntament amb els meus socis desenvolupem programari i treballem en projectes informàtics. Mastermind és la nostra primera app per a mòbil — i esperem que no l'última.",
    contact_h2: "Contacta'ns",
    contact_p: "Tens una pregunta, has trobat un error o vols suggerir una funció? Ens encantarà saber de tu.",
    knuth_fact: "🧠 Ho sabies? Donald Knuth va demostrar el 1976 que qualsevol codi es pot resoldre en 5 intents o menys amb l'algoritme minimax — l'òptim teòric per a la versió clàssica (6 colors, 4 posicions). Resoldre'l en 3 intents és excepcional.",
