    about_h2: "Σχετικά με την Colegio Solutions",
    about_sub: "Μια μικρή εταιρεία λογισμικού κοντά στην Πράγα, στην Τσεχία.",
    about_who_h: "Ποιοι είμαστε",
    about_who_p1: "Η Colegio Solutions s.r.o. είναι μια τσεχική εταιρεία λογισμικού που ιδρύθηκε στη Sibřina, ένα μικρό χωριό ανατολικά της Πράγας. Δημιουργούμε στοχευμένες, προσεγμένες εφαρμογές — εργαλεία και παιχνίδια απλά στη χρήση και ευχάριστα.",
    about_who_p2: "Το Mastermind είναι το πρώτο μας παιχνίδι για κινητά — φτιαγμένο εγγενώς για iOS με SwiftUI και για Android με Kotlin & Jetpack Compose — με βαθύ σεβασμό για το αυθεντικό επιτραπέζιο που προκαλεί τα μυαλά από το 1970.",
