    about_v3_h: "Δίκαιη τιμή",
    about_v3_p: "μία μικρή πληρωμή ξεκλειδώνει τα πάντα. Για πάντα.",
    about_v4_h: "Ποιότητα",
    about_v4_p: "εγγενές SwiftUI και Kotlin/Compose, χωρίς SDK τρίτων, χωρίς διαφημίσεις.",
    about_info_h: "Στοιχεία εταιρείας",
    about_story_h: "Η ιστορία μου",
    about_story_p1: "Το 1985 ήμουν 15 χρονών και ζούσα στην Τσεχοσλοβακία υπό κομμουνιστικό καθεστώς. Τα σύνορα ήταν σφραγισμένα με συρματοπλέγματα, η οικονομία ήταν ερειπωμένη και οι άνθρωποι δεν ήταν ελεύθεροι να ταξιδεύουν ή να σκέφτονται μόνοι τους. Όσοι τολμούσαν να δράσουν είτε ρίσκαραν τη ζωή τους περνώντας τα σύνορα είτε κατέληγαν στη φυλακή. Η ίδια μου η οικογένεια ήταν χωρισμένη: κάποιοι συγγενείς είχαν διαφύγει στο εξωτερικό, άλλοι έμειναν πίσω.",
    about_story_p2: "Ακόμη δεν ξέρω ακριβώς πώς, αλλά οι συγγενείς μου κατάφεραν να περάσουν λαθραία έναν Commodore 64 από τα σύνορα. Ενθουσιάστηκα. Άρχισα να προγραμματίζω — αποθηκεύοντας σε κασέτα — και το πρώτο παιχνίδι που έγραψα ήταν το Mastermind.",
    about_story_p3: "Σαράντα χρόνια αργότερα, επέστρεψα σε αυτό. Αποφάσισα να φτιάξω ξανά το παιχνίδι, αυτή τη φορά για iOS και Android. Είμαι διευθυντής της Colegio Solutions s.r.o., όπου μαζί με τους συνεργάτες μου αναπτύσσουμε λογισμικό και δουλεύουμε σε έργα πληροφορικής. Το Mastermind είναι η πρώτη μας εφαρμογή για κινητά — και ελπίζουμε όχι η τελευταία.",
