    knuth_fact: "🧠 Το ήξερες; Ο Donald Knuth απέδειξε το 1976 ότι κάθε κωδικός μπορεί να λυθεί σε 5 προσπάθειες ή λιγότερες με τον αλγόριθμο minimax — το θεωρητικό βέλτιστο για την κλασική έκδοση (6 χρώματα, 4 θέσεις). Η λύση σε 3 προσπάθειες είναι εξαιρετική.",
