    about_who_p1: "Colegio Solutions s.r.o. este o firmă cehă de software fondată în Sibřina, un mic sat la est de Praga. Creăm aplicații concentrate și bine lucrate — instrumente și jocuri simple de folosit și plăcute.",
    about_who_p2: "Mastermind este primul nostru joc mobil — construit nativ pentru iOS cu SwiftUI și pentru Android cu Kotlin & Jetpack Compose — cu un profund respect pentru jocul de societate original, care pune mințile la încercare din 1970.",
