    about_info_h: "Date despre firmă",
    about_story_h: "Povestea mea",
    about_story_p1: "În 1985 aveam 15 ani și trăiam în Cehoslovacia, sub regimul comunist. Granițele erau închise cu sârmă ghimpată, economia era în ruine, iar oamenii nu erau liberi să călătorească sau să gândească cu capul lor. Cei care îndrăzneau să acționeze fie își riscau viața trecând granița, fie ajungeau la închisoare. Propria mea familie era dezbinată: unele rude fugiseră în străinătate, altele rămăseseră acasă.",
    about_story_p2: "Nici acum nu știu exact cum, dar rudele mele au reușit să treacă ilegal un Commodore 64 peste graniță. Eram încântat. Am început să programez — salvând pe o casetă — iar primul joc pe care l-am scris a fost Mastermind.",
    about_story_p3: "Patruzeci de ani mai târziu, m-am întors la el. Am decis să construiesc din nou jocul, de data aceasta pentru iOS și Android. Sunt directorul Colegio Solutions s.r.o., unde, împreună cu partenerii mei, dezvoltăm software și lucrăm la proiecte IT. Mastermind este prima noastră aplicație mobilă — și sperăm că nu ultima.",
