    about_sub: "Malá softvérová firma neďaleko Prahy v Česku.",
    about_who_h: "Kto sme",
    about_who_p1: "Colegio Solutions s.r.o. je česká softvérová firma založená v Sibřine, malej obci východne od Prahy. Tvoríme cielené, starostlivo vyladené aplikácie — nástroje a hry, ktoré sa jednoducho používajú a prinášajú radosť.",
    about_who_p2: "Mastermind je naša prvá mobilná hra — vytvorená natívne pre iOS v SwiftUI a pre Android v Kotline a Jetpack Compose — s hlbokou úctou k pôvodnej stolovej hre, ktorá preveruje myseľ už od roku 1970.",
