    about_info_h: "Údaje o firme",
    about_story_h: "Môj príbeh",
    about_story_p1: "V roku 1985 som mal 15 rokov a žil som v komunistickom Československu. Hranice boli uzavreté ostnatým drôtom, hospodárstvo bolo v troskách a ľudia nemohli slobodne cestovať ani myslieť. Tí, ktorí sa odvážili konať, buď riskovali život pri prechode hranice, alebo skončili vo väzení. Aj moja rodina bola rozdelená: niektorí príbuzní utiekli do zahraničia, iní zostali doma.",
    about_story_p2: "Dodnes presne neviem ako, ale mojim príbuzným sa podarilo prepašovať cez hranicu Commodore 64. Bol som nadšený. Začal som programovať — ukladal som na kazetu — a prvou hrou, ktorú som napísal, bol Mastermind.",
    about_story_p3: "O štyridsať rokov neskôr som sa k nemu vrátil. Rozhodol som sa hru vytvoriť znova, tentoraz pre iOS a Android. Som konateľom spoločnosti Colegio Solutions s.r.o., kde spolu s partnermi vyvíjame softvér a pracujeme na IT projektoch. Mastermind je naša prvá mobilná aplikácia — a dúfajme, že nie posledná.",
