    about_story_p2: "Jeg vet fortsatt ikke helt hvordan, men slektningene mine klarte å smugle en Commodore 64 over grensen. Jeg var overlykkelig. Jeg begynte å programmere — og lagret på kassett — og det første spillet jeg skrev, var Mastermind.",
    about_story_p3: "Førti år senere vendte jeg tilbake til det. Jeg bestemte meg for å lage spillet på nytt, denne gangen for iOS og Android. Jeg er daglig leder i Colegio Solutions s.r.o., der jeg sammen med partnerne mine utvikler programvare og jobber med IT-prosjekter. Mastermind er vår første mobilapp — og forhåpentligvis ikke den siste.",
