    about_who_p1: "A Colegio Solutions s.r.o. é uma empresa checa de software fundada em Sibřina, uma pequena aldeia a leste de Praga. Criamos aplicações focadas e cuidadosamente trabalhadas — ferramentas e jogos simples de usar e agradáveis.",
    about_who_p2: "Mastermind é o nosso primeiro jogo para telemóvel — desenvolvido de forma nativa para iOS com SwiftUI e para Android com Kotlin e Jetpack Compose — com profundo respeito pelo jogo de tabuleiro original que desafia mentes desde 1970.",
