    about_info_h: "Informações da empresa",
    about_story_h: "A minha história",
    about_story_p1: "Em 1985 tinha 15 anos e vivia na Checoslováquia sob o regime comunista. As fronteiras estavam fechadas com arame farpado, a economia estava em ruínas e as pessoas não eram livres de viajar nem de pensar por si próprias. Quem se atrevia a agir arriscava a vida a atravessar a fronteira ou acabava na prisão. A minha própria família estava dividida: alguns familiares tinham fugido para o estrangeiro, outros ficaram.",
    about_story_p2: "Ainda hoje não sei exatamente como, mas os meus familiares conseguiram contrabandear um Commodore 64 através da fronteira. Fiquei entusiasmadíssimo. Comecei a programar — a gravar numa cassete — e o primeiro jogo que escrevi foi o Mastermind.",
    about_story_p3: "Quarenta anos depois, voltei a ele. Decidi criar o jogo de novo, desta vez para iOS e Android. Sou diretor da Colegio Solutions s.r.o., onde, juntamente com os meus sócios, desenvolvemos software e trabalhamos em projetos de TI. Mastermind é a nossa primeira app móvel — e esperemos que não a última.",
