    about_story_h: "Kisah Saya",
    about_story_p1: "Pada tahun 1985, saya berumur 15 tahun dan tinggal di Czechoslovakia di bawah pemerintahan komunis. Sempadan ditutup dengan kawat berduri, ekonomi musnah, dan rakyat tidak bebas untuk mengembara atau berfikir sendiri. Mereka yang berani bertindak sama ada mempertaruhkan nyawa menyeberangi sempadan atau berakhir di penjara. Keluarga saya sendiri berpecah: sesetengah saudara melarikan diri ke luar negara, yang lain tinggal.",
