    about_h2: "אודות Colegio Solutions",
    about_sub: "חברת תוכנה קטנה ליד פראג, צ'כיה.",
    about_who_h: "מי אנחנו",
    about_who_p1: "Colegio Solutions s.r.o. היא חברת תוכנה צ'כית שנוסדה בסיבז'ינה, כפר קטן מזרחית לפראג. אנחנו בונים אפליקציות ממוקדות ומעוצבות בקפידה — כלים ומשחקים פשוטים לשימוש ומהנים.",
    about_who_p2: "Mastermind הוא המשחק הנייד הראשון שלנו — נבנה באופן טבעי ל-iOS עם SwiftUI ול-Android עם Kotlin ו-Jetpack Compose — מתוך כבוד עמוק למשחק הלוח המקורי שמאתגר מוחות מאז 1970.",
