    about_v2_p: "עיצוב ידידותי לעיוורי צבעים, מתורגם ל-50 שפות.",
    about_v3_h: "תמחור הוגן",
    about_v3_p: "תשלום קטן אחד פותח הכל. לתמיד.",
    about_v4_h: "איכות",
    about_v4_p: "SwiftUI ו-Kotlin/Compose מקוריים, בלי SDK של צד שלישי, בלי פרסומות.",
    about_info_h: "פרטי החברה",
    about_story_h: "הסיפור שלי",
    about_story_p1: "ב-1985 הייתי בן 15 וחייתי בצ'כוסלובקיה תחת שלטון קומוניסטי. הגבולות היו סגורים בגדרות תיל, הכלכלה הייתה הרוסה, ואנשים לא היו חופשיים לנסוע או לחשוב בעצמם. מי שהעז לפעול סיכן את חייו בחציית הגבול או הגיע לכלא. גם המשפחה שלי הייתה מפולגת: חלק מהקרובים ברחו לחו\"ל, אחרים נשארו.",
    about_story_p2: "עד היום אני לא יודע בדיוק איך, אבל קרוביי הצליחו להבריח מעבר לגבול Commodore 64. הייתי מאושר. התחלתי לתכנת — שמרתי על קלטת — והמשחק הראשון שכתבתי היה Mastermind.",
    about_story_p3: "ארבעים שנה אחר כך חזרתי אליו. החלטתי לבנות את המשחק מחדש, הפעם ל-iOS ול-Android. אני המנהל של Colegio Solutions s.r.o., שבה אני מפתח תוכנה ועובד על פרויקטי IT יחד עם השותפים שלי. Mastermind היא האפליקציה הניידת הראשונה שלנו — ואני מקווה שלא האחרונה.",
    contact_h2: "צרו קשר",
    contact_p: "יש לכם שאלה, מצאתם באג או רוצים להציע תכונה? נשמח לשמוע מכם.",
