    about_h2: "Colegio Solutions সম্পর্কে",
    about_sub: "চেক প্রজাতন্ত্রের প্রাগের কাছে একটি ছোট সফটওয়্যার কোম্পানি।",
    about_who_h: "আমরা কারা",
    about_who_p1: "Colegio Solutions s.r.o. একটি চেক সফটওয়্যার কোম্পানি, যা প্রাগের পূর্বে ছোট গ্রাম সিবরঝিনায় প্রতিষ্ঠিত। আমরা মনোযোগী ও যত্নে তৈরি অ্যাপ বানাই — এমন টুল ও খেলা যা ব্যবহারে সহজ এবং আনন্দদায়ক।",
    about_who_p2: "Mastermind আমাদের প্রথম মোবাইল গেম — iOS-এর জন্য SwiftUI এবং Android-এর জন্য Kotlin ও Jetpack Compose দিয়ে নেটিভভাবে তৈরি — সেই মূল বোর্ড গেমের প্রতি গভীর শ্রদ্ধা নিয়ে, যা ১৯৭০ সাল থেকে মনকে চ্যালেঞ্জ করে আসছে।",
    about_val_h: "আমাদের মূল্যবোধ",
