    about_h2: "Colegio Solutions बद्दल",
    about_sub: "चेक प्रजासत्ताकमधील प्रागजवळची एक छोटी सॉफ्टवेअर कंपनी.",
    about_who_h: "आम्ही कोण आहोत",
    about_who_p1: "Colegio Solutions s.r.o. ही एक चेक सॉफ्टवेअर कंपनी आहे, जिची स्थापना प्रागच्या पूर्वेकडील सिब्रझिना या छोट्या गावात झाली. आम्ही केंद्रित आणि काळजीपूर्वक बनवलेली अ‍ॅप्स तयार करतो — वापरण्यास सोपी आणि आनंददायक साधने व खेळ.",
    about_who_p2: "Mastermind हा आमचा पहिला मोबाइल खेळ आहे — iOS साठी SwiftUI आणि Android साठी Kotlin व Jetpack Compose वापरून नेटिव्ह पद्धतीने बनवलेला — 1970 पासून बुद्धीला आव्हान देणाऱ्या मूळ बोर्ड गेमबद्दल खोल आदर बाळगून.",
    about_val_h: "आमची मूल्ये",
    about_v1_h: "साधेपणा",
