    hero_h1: "ਕੋਡ ਤੋੜੋ।<br>ਦਿਮਾਗ਼ 'ਤੇ ਕਾਬੂ ਪਾਓ।",
    hero_sub: "ਕੋਡ ਤੋੜਨ ਵਾਲੀ ਕਲਾਸਿਕ ਖੇਡ, iPhone ਅਤੇ Android ਲਈ ਨਵੇਂ ਰੂਪ ਵਿੱਚ। ਆਪਣੇ ਅਨੁਮਾਨ ਖ਼ਤਮ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਗੁਪਤ ਰੰਗਾਂ ਦਾ ਕ੍ਰਮ ਲੱਭੋ।",
