    features_h2: "Mastermind ਦੀ ਹਰ ਉਹ ਚੀਜ਼ ਜੋ ਤੁਹਾਨੂੰ ਪਸੰਦ ਹੈ",
    features_sub: "ਆਧੁਨਿਕ ਅੰਦਾਜ਼ ਵਿੱਚ ਕਲਾਸਿਕ ਗੇਮਪਲੇ — ਸਾਫ਼ ਡਿਜ਼ਾਈਨ, ਸਮਾਰਟ ਫੀਡਬੈਕ ਅਤੇ ਮੁਸ਼ਕਲ ਦੇ ਕਈ ਪੱਧਰ।",
