    f1_p: "ਆਸਾਨ (4 ਰੰਗ) ਤੋਂ ਦੁਹਰਾਏ ਜਾਣ ਵਾਲੇ ਰੰਗਾਂ ਵਾਲੇ ਕਲਾਸਿਕ ਤੱਕ, ਅਤੇ 5 ਸਥਾਨਾਂ ਵਾਲੇ ਔਖੇ ਪੱਧਰ ਤੱਕ। ਹਰ ਕਿਸੇ ਲਈ ਇੱਕ ਚੁਣੌਤੀ।",
    f2_h: "ਸਮਾਂਬੱਧ ਮੋਡ",
    f2_p: "ਘੜੀ ਨਾਲ ਮੁਕਾਬਲਾ ਕਰੋ। 3 ਮਿੰਟਾਂ ਤੋਂ ਘੱਟ ਵਿੱਚ ਕੋਡ ਹੱਲ ਕਰੋ ਅਤੇ ਦੁੱਗਣਾ ਸਕੋਰ ਪਾਓ। ਸਿਰਫ਼ ਬਹਾਦਰਾਂ ਲਈ।",
    f3_h: "ਪਹੁੰਚਯੋਗ ਰੰਗ",
    f3_p: "ਰੰਗ Okabe-Ito ਪੈਲੇਟ ਵਿੱਚੋਂ ਚੁਣੇ ਗਏ ਹਨ — ਰੰਗ-ਅੰਨ੍ਹੇਪਣ ਵਾਲੇ ਲੋਕ ਵੀ ਇਹਨਾਂ ਨੂੰ ਪਛਾਣ ਸਕਦੇ ਹਨ।",
    f4_h: "ਗਲੋਬਲ ਲੀਡਰਬੋਰਡ",
    f4_p: "ਦੁਨੀਆ ਭਰ ਦੇ ਖਿਡਾਰੀਆਂ ਨਾਲ ਮੁਕਾਬਲਾ ਕਰੋ। ਦੇਖੋ ਕਿ ਵਿਸ਼ਵ ਦਰਜਾਬੰਦੀ ਵਿੱਚ ਤੁਸੀਂ ਕਿੱਥੇ ਹੋ।",
    f5_h: "50 ਭਾਸ਼ਾਵਾਂ",
    f5_p: "ਚੈੱਕ, ਅੰਗਰੇਜ਼ੀ, ਜਰਮਨ, ਫ਼ਰਾਂਸੀਸੀ, ਸਪੇਨੀ, ਜਪਾਨੀ, ਅਰਬੀ, ਪੰਜਾਬੀ ਅਤੇ ਹੋਰ ਕਈ ਭਾਸ਼ਾਵਾਂ ਵਿੱਚ ਪੂਰਾ ਅਨੁਵਾਦ।",
    f6_h: "ਫੀਡਬੈਕ ਪੈੱਗ",
    f6_p: "ਕਾਲਾ ਪੈੱਗ = ਸਹੀ ਰੰਗ, ਸਹੀ ਸਥਾਨ। ਚਿੱਟਾ ਪੈੱਗ = ਸਹੀ ਰੰਗ, ਗ਼ਲਤ ਸਥਾਨ। ਬਿਲਕੁਲ ਅਸਲ ਖੇਡ ਵਾਂਗ।",
    pro_badge: "Mastermind Pro",
    pro_h2: "ਪੂਰਾ ਅਨੁਭਵ ਅਨਲੌਕ ਕਰੋ",
