    pro_l1: "ਕਲਾਸਿਕ ਪੱਧਰ — 6 ਰੰਗ, ਦੁਹਰਾਉਣ ਦੀ ਇਜਾਜ਼ਤ",
    pro_l2: "ਔਖਾ ਪੱਧਰ — 6 ਰੰਗ, 5 ਸਥਾਨ",
