    trn_h2: "🏅 ਟੂਰਨਾਮੈਂਟ",
    trn_sub: "ਹਰ ਕੋਈ ਇੱਕੋ ਗੁਪਤ ਕੋਡ ਹੱਲ ਕਰਦਾ ਹੈ — ਹਰ ਖਿਡਾਰੀ ਦੀ ਇੱਕ ਕੋਸ਼ਿਸ਼, ਨਿਰਪੱਖ ਮੁਕਾਬਲਾ। ਐਪ ਵਿੱਚ ਟੂਰਨਾਮੈਂਟ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਵੋ, ਆਪਣਾ ਕੋਡ ਲਓ, ਟੂਰਨਾਮੈਂਟ ਦੌਰਾਨ ਕਦੇ ਵੀ ਖੇਡੋ, ਅਤੇ ਤੁਹਾਡਾ ਨਤੀਜਾ ਆਪਣੇ-ਆਪ ਜਮ੍ਹਾਂ ਹੋ ਜਾਵੇਗਾ। ਜੇਤੂ ਉਹ ਹੈ ਜੋ ਸਭ ਤੋਂ ਘੱਟ ਅਨੁਮਾਨਾਂ ਵਿੱਚ ਕੋਡ ਤੋੜੇ।",
