    lb_h2: "🏆 గ్లోబల్ లీడర్‌బోర్డ్",
    lb_sub: "ప్రపంచం నలుమూలల నుండి అగ్ర ఆటగాళ్లు. యాప్ డౌన్‌లోడ్ చేసి మీ స్థానం దక్కించుకోండి.",
