    badge: "App Store & Google Play ನಲ್ಲಿ ಲಭ್ಯ",
    hero_h1: "ಕೋಡ್ ಭೇದಿಸಿ.<br>ಮನಸ್ಸನ್ನು ಗೆಲ್ಲಿ.",
    hero_sub: "iPhone ಮತ್ತು Android ಗಾಗಿ ಹೊಸ ರೂಪದಲ್ಲಿ ಕ್ಲಾಸಿಕ್ ಕೋಡ್-ಭೇದಿಸುವ ಆಟ. ನಿಮ್ಮ ಊಹೆಗಳು ಮುಗಿಯುವ ಮೊದಲು ರಹಸ್ಯ ಬಣ್ಣಗಳ ಅನುಕ್ರಮವನ್ನು ಪತ್ತೆಹಚ್ಚಿ.",
    hero_note: "ಉಚಿತ · iPhone & Android · iOS 15.6+ · Android 8+",
    dl_appstore_small: "ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ",
    dl_appstore: "App Store",
    dl_google_small: "ಪಡೆಯಿರಿ",
    dl_google: "Google Play",
    features_h2: "Mastermind ನಲ್ಲಿ ನೀವು ಇಷ್ಟಪಡುವ ಎಲ್ಲವೂ",
    features_sub: "ಆಧುನಿಕ ಸ್ಪರ್ಶದೊಂದಿಗೆ ಕ್ಲಾಸಿಕ್ ಆಟ — ಸ್ವಚ್ಛ ವಿನ್ಯಾಸ, ಬುದ್ಧಿವಂತ ಪ್ರತಿಕ್ರಿಯೆ ಮತ್ತು ಹಲವು ಕಷ್ಟದ ಮಟ್ಟಗಳು.",
    f1_h: "4 ಕಷ್ಟದ ಮಟ್ಟಗಳು",
    f1_p: "ಸುಲಭ (4 ಬಣ್ಣಗಳು) ದಿಂದ ಪುನರಾವರ್ತಿತ ಬಣ್ಣಗಳೊಂದಿಗೆ ಕ್ಲಾಸಿಕ್ ವರೆಗೆ, 5 ಸ್ಥಾನಗಳ ಕಷ್ಟ ವರೆಗೆ. ಎಲ್ಲರಿಗೂ ಒಂದು ಸವಾಲು.",
    f2_h: "ಸಮಯ-ಸೀಮಿತ ಮೋಡ್",
    f2_p: "ಗಡಿಯಾರದ ವಿರುದ್ಧ ಓಡಿ. 3 ನಿಮಿಷಗಳೊಳಗೆ ಕೋಡ್ ಭೇದಿಸಿ ಎರಡು ಪಟ್ಟು ಸ್ಕೋರ್ ಪಡೆಯಿರಿ. ಧೈರ್ಯಶಾಲಿಗಳಿಗೆ ಮಾತ್ರ.",
    f3_h: "ಎಲ್ಲರಿಗೂ ಸುಲಭ ಬಣ್ಣಗಳು",
    f3_p: "ಬಣ್ಣಗಳನ್ನು Okabe-Ito ಪ್ಯಾಲೆಟ್‌ನಿಂದ ಆಯ್ಕೆ ಮಾಡಲಾಗಿದೆ — ಬಣ್ಣಗುರುಡು ಇರುವವರೂ ಗುರುತಿಸಬಹುದು.",
    f4_h: "ಜಾಗತಿಕ ಲೀಡರ್‌ಬೋರ್ಡ್",
    f4_p: "ವಿಶ್ವದಾದ್ಯಂತದ ಆಟಗಾರರೊಂದಿಗೆ ಸ್ಪರ್ಧಿಸಿ. ಜಾಗತಿಕ ಶ್ರೇಯಾಂಕದಲ್ಲಿ ನಿಮ್ಮ ಸ್ಥಾನ ನೋಡಿ.",
    f5_h: "50 ಭಾಷೆಗಳು",
    f5_p: "ಚೆಕ್, ಇಂಗ್ಲಿಷ್, ಜರ್ಮನ್, ಫ್ರೆಂಚ್, ಸ್ಪ್ಯಾನಿಷ್, ಜಪಾನೀಸ್, ಅರೇಬಿಕ್, ಕನ್ನಡ ಮತ್ತು ಇನ್ನೂ ಹಲವು ಭಾಷೆಗಳಲ್ಲಿ ಸಂಪೂರ್ಣ ಅನುವಾದ.",
    f6_h: "ಪ್ರತಿಕ್ರಿಯೆ ಪೆಗ್‌ಗಳು",
    f6_p: "ಕಪ್ಪು ಪೆಗ್ = ಸರಿಯಾದ ಬಣ್ಣ, ಸರಿಯಾದ ಸ್ಥಾನ. ಬಿಳಿ ಪೆಗ್ = ಸರಿಯಾದ ಬಣ್ಣ, ತಪ್ಪು ಸ್ಥಾನ. ಮೂಲ ಆಟದಂತೆಯೇ.",
    pro_badge: "Mastermind Pro",
    pro_h2: "ಪೂರ್ಣ ಅನುಭವವನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಿ",
    pro_p: "ಒಂದೇ ಬಾರಿ ಖರೀದಿ. ಚಂದಾದಾರಿಕೆ ಇಲ್ಲ. ಜಾಹೀರಾತುಗಳಿಲ್ಲ. ಎಂದೆಂದಿಗೂ ಪೂರ್ಣ ಆಟ.",
    pro_l1: "ಕ್ಲಾಸಿಕ್ ಮಟ್ಟ — ಪುನರಾವರ್ತನೆಗೆ ಅನುಮತಿಸಿದ 6 ಬಣ್ಣಗಳು",
    pro_l2: "ಕಷ್ಟ ಮಟ್ಟ — 6 ಬಣ್ಣಗಳು, 5 ಸ್ಥಾನಗಳು",
    pro_l3: "ಸಮಯ-ಸೀಮಿತ ಮೋಡ್ — ಎರಡು ಪಟ್ಟು ಸ್ಕೋರ್",
    pro_l4: "ವಿವರವಾದ ಅಂಕಿಅಂಶಗಳು",
    pro_price: "$1.99 · ಒಂದೇ ಬಾರಿ ಪಾವತಿ",
    trn_h2: "🏅 ಟೂರ್ನಮೆಂಟ್‌ಗಳು",
    trn_sub: "ಎಲ್ಲರೂ ಒಂದೇ ರಹಸ್ಯ ಕೋಡ್ ಭೇದಿಸುತ್ತಾರೆ — ಪ್ರತಿ ಆಟಗಾರನಿಗೆ ಒಂದೇ ಪ್ರಯತ್ನ, ನ್ಯಾಯಯುತ ಸ್ಪರ್ಧೆ. ಆ್ಯಪ್‌ನಲ್ಲಿ ಟೂರ್ನಮೆಂಟ್‌ಗೆ ಸೇರಿ, ನಿಮ್ಮ ಕೋಡ್ ಪಡೆಯಿರಿ, ಟೂರ್ನಮೆಂಟ್ ಅವಧಿಯಲ್ಲಿ ಯಾವಾಗ ಬೇಕಾದರೂ ಆಡಿ — ನಿಮ್ಮ ಫಲಿತಾಂಶ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಸಲ್ಲಿಕೆಯಾಗುತ್ತದೆ. ಕಡಿಮೆ ಊಹೆಗಳಲ್ಲಿ ಕೋಡ್ ಭೇದಿಸಿದವರೇ ವಿಜೇತರು.",
