    hero_sub: "iPhone-നും Android-നുമായി പുതുക്കിയ ക്ലാസിക് കോഡ് തകർക്കൽ ഗെയിം. ഊഹങ്ങൾ തീരുന്നതിനു മുമ്പ് രഹസ്യ നിറക്രമം കണ്ടെത്തൂ.",
