    features_sub: "ആധുനിക സ്പർശമുള്ള ക്ലാസിക് ഗെയിംപ്ലേ — വൃത്തിയുള്ള ഡിസൈൻ, സ്മാർട്ട് ഫീഡ്‌ബാക്ക്, പല ബുദ്ധിമുട്ട് നിലകൾ.",
