    f1_p: "എളുപ്പം (4 നിറങ്ങൾ) മുതൽ ആവർത്തിക്കുന്ന നിറങ്ങളുള്ള ക്ലാസിക് വരെ, 5 സ്ഥാനങ്ങളുള്ള ബുദ്ധിമുട്ടുള്ളത് വരെ. എല്ലാവർക്കും ഒരു വെല്ലുവിളി.",
    f2_h: "ടൈംഡ് മോഡ്",
    f2_p: "സമയത്തോട് മത്സരിക്കൂ. 3 മിനിറ്റിനുള്ളിൽ കോഡ് പരിഹരിച്ച് ഇരട്ടി സ്കോർ നേടൂ. ധൈര്യശാലികൾക്ക് മാത്രം.",
    f3_h: "എല്ലാവർക്കും കാണാവുന്ന നിറങ്ങൾ",
    f3_p: "നിറങ്ങൾ Okabe-Ito പാലറ്റിൽ നിന്ന് തിരഞ്ഞെടുത്തവ — വർണാന്ധതയുള്ളവർക്കും തിരിച്ചറിയാം.",
    f4_h: "ആഗോള ലീഡർബോർഡ്",
    f4_p: "ലോകമെമ്പാടുമുള്ള കളിക്കാരുമായി മത്സരിക്കൂ. ആഗോള റാങ്കിംഗിൽ നിങ്ങളുടെ സ്ഥാനം കാണൂ.",
    f5_h: "50 ഭാഷകൾ",
    f5_p: "ചെക്ക്, ഇംഗ്ലീഷ്, ജർമ്മൻ, ഫ്രഞ്ച്, സ്പാനിഷ്, ജാപ്പനീസ്, അറബിക്, മലയാളം എന്നിവയുൾപ്പെടെ നിരവധി ഭാഷകളിൽ പൂർണ്ണമായി ലഭ്യം.",
    f6_h: "ഫീഡ്‌ബാക്ക് പെഗുകൾ",
    f6_p: "കറുത്ത പെഗ് = ശരിയായ നിറം, ശരിയായ സ്ഥാനം. വെളുത്ത പെഗ് = ശരിയായ നിറം, തെറ്റായ സ്ഥാനം. യഥാർത്ഥ ഗെയിം പോലെ തന്നെ.",
    pro_badge: "Mastermind Pro",
    pro_h2: "പൂർണ്ണ അനുഭവം അൺലോക്ക് ചെയ്യൂ",
    pro_p: "ഒറ്റത്തവണ വാങ്ങൽ. സബ്‌സ്ക്രിപ്ഷനില്ല. പരസ്യങ്ങളില്ല. എന്നെന്നേക്കുമായി പൂർണ്ണ ഗെയിം.",
    pro_l1: "ക്ലാസിക് നില — ആവർത്തനം അനുവദിക്കുന്ന 6 നിറങ്ങൾ",
