    trn_sub: "എല്ലാവരും ഒരേ രഹസ്യ കോഡ് പരിഹരിക്കുന്നു — ഓരോ കളിക്കാരനും ഒരു ശ്രമം, ന്യായമായ പോരാട്ടം. ആപ്പിൽ ഒരു ടൂർണമെന്റിൽ ചേരൂ, നിങ്ങളുടെ കോഡ് നേടൂ, ടൂർണമെന്റ് കാലയളവിൽ എപ്പോൾ വേണമെങ്കിലും കളിക്കൂ — ഫലം സ്വയമേവ സമർപ്പിക്കപ്പെടും. ഏറ്റവും കുറഞ്ഞ ഊഹങ്ങളിൽ കോഡ് തകർക്കുന്നയാളാണ് വിജയി.",
