    hero_sub: "iPhone ଓ Android ପାଇଁ ନୂଆ ରୂପରେ କ୍ଲାସିକ କୋଡ୍-ଭାଙ୍ଗିବା ଖେଳ। ଆପଣଙ୍କ ଅନୁମାନ ସରିବା ପୂର୍ବରୁ ଗୁପ୍ତ ରଙ୍ଗ କ୍ରମ ଖୋଜି ବାହାର କରନ୍ତୁ।",
