    features_sub: "ଆଧୁନିକ ସ୍ପର୍ଶ ସହ କ୍ଲାସିକ ଖେଳ — ସଫା ଡିଜାଇନ, ସ୍ମାର୍ଟ ଫିଡବ୍ୟାକ ଓ ଅନେକ କଠିନତା ସ୍ତର।",
    f1_h: "4ଟି କଠିନତା ସ୍ତର",
    f1_p: "ସହଜ (4 ରଙ୍ଗ) ଠାରୁ ପୁନରାବୃତ୍ତ ରଙ୍ଗ ସହ କ୍ଲାସିକ ପର୍ଯ୍ୟନ୍ତ, 5 ସ୍ଥାନ ସହ କଠିନ ପର୍ଯ୍ୟନ୍ତ। ସମସ୍ତଙ୍କ ପାଇଁ ଏକ ଚ୍ୟାଲେଞ୍ଜ।",
